<script setup lang="ts">
import { ref } from 'vue'
import { Activity, Search, ShieldCheck } from 'lucide-vue-next'
import { useResource } from '../api'
import type { AuditEvent, Detail, Routine } from '../types'
import { date, json } from '../format'
import PageTitle from '../components/PageTitle.vue'
import ResourceState from '../components/ResourceState.vue'
const events = useResource<AuditEvent[]>('/audit-events', []), metrics = useResource<Detail>('/governance/metrics', {}), policies = useResource<Detail[]>('/governance/policies', []), budgets = useResource<Detail[]>('/governance/budgets', []), routines = useResource<Routine[]>('/routines', [])
const tab = ref('audit'), query = ref('')
</script>
<template>
  <PageTitle title="履职与治理" subtitle="从真实业务结果评价团队，查看责任、权限、预算与可追溯操作。" eyebrow="GOVERNANCE / OUTCOMES, NOT OUTPUT VOLUME"/>
  <section class="panel governance-overview"><div class="panel-heading"><h2><Activity :size="18"/>履职观测</h2><span class="caption">后端计算的可核验指标</span></div><ResourceState :loading="metrics.loading.value" :error="metrics.error.value" :empty="!Object.keys(metrics.data.value).length" description="尚未形成履职指标" @retry="metrics.load"><dl class="metric-dictionary"><template v-for="(value,key) in metrics.data.value" :key="key"><dt>{{ key }}</dt><dd>{{ typeof value === 'object' ? json(value) : value }}</dd></template></dl></ResourceState><p class="caption">Task 数量无法单独代表员工价值。指标应结合目标达成、验证质量、交接结果、复发与人工介入成本。</p></section>
  <el-tabs v-model="tab"><el-tab-pane label="审计日志" name="audit"/><el-tab-pane label="授权策略" name="policies"/><el-tab-pane label="预算与成本" name="budgets"/><el-tab-pane label="持续职责观测" name="routines"/></el-tabs>
  <section v-if="tab === 'audit'" class="panel audit-panel"><div class="panel-heading"><h2><ShieldCheck :size="18"/>可信操作记录</h2><el-input v-model="query" :prefix-icon="Search" clearable placeholder="搜索动作、主体或内容" aria-label="搜索审计日志"/></div><ResourceState :loading="events.loading.value" :error="events.error.value" :empty="!events.data.value.length" description="暂无可见审计记录" @retry="events.load"><el-table :data="events.data.value.filter(event => !query || `${event.type} ${event.actor_id} ${event.summary}`.includes(query)).slice().reverse()"><el-table-column prop="seq" label="序号" width="75"/><el-table-column prop="type" label="动作" min-width="180"/><el-table-column prop="summary" label="结果与说明" min-width="280"/><el-table-column prop="actor_id" label="可信主体" min-width="180"/><el-table-column prop="entity_ref" label="业务引用" min-width="180"/><el-table-column prop="revision" label="版本" width="70"/><el-table-column label="时间" min-width="175"><template #default="{ row }">{{ date(row.created_at) }}</template></el-table-column></el-table></ResourceState></section>
  <section v-else-if="tab === 'policies'" class="panel governance-records"><ResourceState :loading="policies.loading.value" :error="policies.error.value" :empty="!policies.data.value.length" description="暂无可见策略记录" @retry="policies.load"><article v-for="(policy,index) in policies.data.value" :key="index" class="mini-card"><pre class="code-block">{{ json(policy) }}</pre></article></ResourceState><div class="soft-note"><p>员工不能自行扩权。组织强制规则、岗位上限、责任范围和具体工作授权由后端统一检查。</p></div></section>
  <section v-else-if="tab === 'budgets'" class="panel governance-records"><ResourceState :loading="budgets.loading.value" :error="budgets.error.value" :empty="!budgets.data.value.length" description="尚无可见真实预算记录" @retry="budgets.load"><el-table :data="budgets.data.value"><el-table-column prop="name" label="员工" min-width="160"/><el-table-column prop="employee_id" label="归属主体" min-width="220"/><el-table-column prop="daily_token_budget" label="每日 Token 预算" min-width="150"/><el-table-column prop="decision_tokens" label="今日自主决策 Tokens" min-width="180"/><el-table-column prop="execution_tokens" label="今日工程执行 Tokens" min-width="180"/></el-table></ResourceState></section>
  <section v-else class="panel"><ResourceState :loading="routines.loading.value" :error="routines.error.value" :empty="!routines.data.value.length" description="尚未安排周期职责" @retry="routines.load"><el-table :data="routines.data.value"><el-table-column prop="title" label="持续职责" min-width="200"/><el-table-column label="员工" min-width="180"><template #default="{ row }"><RouterLink :to="`/employees/${row.employee_id}`" class="text-link">{{ row.employee_id }}</RouterLink></template></el-table-column><el-table-column prop="kind" label="触发类型" width="120"/><el-table-column prop="schedule" label="规则" min-width="140"/><el-table-column prop="timezone" label="时区" min-width="140"/><el-table-column label="启用 / 锁定" min-width="130"><template #default="{ row }">{{ row.enabled ? '启用' : '暂停' }} / {{ row.locked ? '人类锁定' : '未锁定' }}</template></el-table-column><el-table-column label="下次检查" min-width="170"><template #default="{ row }">{{ date(row.next_due_at) }}</template></el-table-column></el-table></ResourceState></section>
</template>
